// kat.test.mjs — cross-language known-answer test for the relay E2E crypto.
//
// Recomputes the transcript MAC and a sealed frame from FIXED inputs using
// this WebCrypto implementation, and asserts they equal the vectors the Swift
// implementation produced (committed to relay-kat-vectors.json, generated by
// RelayCryptoVectorTests). A match proves the two implementations agree byte
// for byte — the guarantee that a phone and Mac can actually talk.
//
// The fixed inputs mirror RelayCryptoVectorTests.swift exactly.

import assert from 'node:assert/strict'
import { readFileSync } from 'node:fs'
import { test } from 'node:test'
import { RelaySession, b64, transcriptMAC } from './relay-crypto.mjs'

const range = (n, f) => new Uint8Array(Array.from({ length: n }, (_, i) => f(i) & 0xff))

const e2eKey = range(32, (i) => i)
const sharedSecret = range(32, (i) => 0x40 + i)
const clientSalt = range(16, (i) => 0x10 + i)
const hostSalt = range(16, (i) => 0xa0 + i)
const deviceID = 'phone-kat-1'
const clientEph = range(32, (i) => 0x80 + i)
const hostEph = range(32, (i) => 0xc0 + i * 3)
const plaintext = new TextEncoder().encode('known-answer-plaintext')

const vectorsPath = new URL('./relay-kat-vectors.json', import.meta.url)

test('transcript MAC matches the Swift vector', async () => {
  const mac = await transcriptMAC(e2eKey, deviceID, clientSalt, hostSalt, clientEph, hostEph)
  const vectors = JSON.parse(readFileSync(vectorsPath, 'utf8'))
  assert.equal(b64(mac), vectors.transcriptMAC, 'JS and Swift transcript MAC disagree')
})

test('sealed frame matches the Swift vector and opens on the host session', async () => {
  const client = await RelaySession.create({
    e2eKey,
    sharedSecret,
    clientSalt,
    hostSalt,
    isHost: false,
  })
  const sealed = await client.seal(plaintext)
  const vectors = JSON.parse(readFileSync(vectorsPath, 'utf8'))
  assert.equal(b64(sealed), vectors.sealedFrame, 'JS and Swift AES-GCM output disagree')

  // And the JS host session opens the JS client frame (round-trip sanity).
  const host = await RelaySession.create({
    e2eKey,
    sharedSecret,
    clientSalt,
    hostSalt,
    isHost: true,
  })
  const opened = await host.open(sealed)
  assert.equal(new TextDecoder().decode(opened), 'known-answer-plaintext')
})
